.c-product { --product-green: #007c3f; --product-orange: #f36b39; margin-top: -5px; padding: 0 0 140px; color: #111; }
.c-product__breadcrumb { width: 508px; height: 70px; display: flex; gap: 8px; align-items: start; font-size: 12px; color: #777; }
.c-product__breadcrumb a { color: inherit; text-decoration: none; }
.c-product__intro { display: grid; grid-template-columns: repeat(12, 1fr); column-gap: 20px; align-items: start; }
.c-product__gallery { grid-column: 1 / 7; height: 710px; border: 1px solid #dedede; border-radius: 22px; display: grid; place-items: center; overflow: hidden; }
.c-product__gallery img { width: 82%; height: 82%; object-fit: contain; }
.c-product__summary { grid-column: 7 / 13; padding: 4px 0 0 0; }
.c-product__summary-main { position: relative; top: -3px; min-height: 571px; }
.c-product__summary h1 { font-size: 42px; line-height: 1.1; margin: 0 0 16px; }
.c-product__meta, .c-product__wholesale { font-size: 16px; line-height: 2; margin: 0 0 14px; }
.c-product__price { font-size: 22px; margin: 14px 0 4px; }.c-product__price bdi { color: var(--product-green); font-size: 34px; font-weight: 700; }
.c-product__cart { display: flex; gap: 8px; margin: 12px 0; }.c-product__cart input { width: 84px; border: 1px solid #333; border-radius: 22px; padding: 9px 14px; }
